const VERSION='imagine-four-offline-v12';
const paths=['./','./index.html','./styles.css?v=classroom-flow','./app.mjs?v=classroom-flow','./core.mjs?v=scrapbook-flow','./core.mjs?v=classroom-tools','./core.mjs?v=classroom-flow','./render.mjs?v=scrapbook-flow','./image-tools.mjs','./segment-client.mjs','./segment-worker.js','./storage.mjs?v=classroom-tools','./brush.mjs','./extras.mjs?v=scrapbook-flow','./preset-bundle.mjs?v=background-gallery','./background-catalog.mjs?v=background-gallery','./background-catalog.mjs?v=mobile-ux','./photo-adjust.mjs','./vendor/mediapipe/vision_bundle.js','./vendor/mediapipe/wasm/vision_wasm_internal.js','./vendor/mediapipe/wasm/vision_wasm_internal.wasm','./vendor/mediapipe/wasm/vision_wasm_module_internal.js','./vendor/mediapipe/wasm/vision_wasm_module_internal.wasm','./vendor/models/selfie_segmenter.tflite',...['space','ocean','forest','dinosaur','clouds','stage','classroom','party'].map(x=>'./assets/backgrounds/'+x+'.svg'),'./assets/demo-person.svg',...['track-finish','graduation-wall','library-maze','science-lab','school-crosswalk','cherry-lane','summer-picnic','autumn-station','snowman-village','rainy-alley','aurora-field','volcano-field','desert-dunes','waterfall-bridge','firefly-cave','hanok-alley','airport-gate','pyramids','canal-bridge','night-market','giant-desk','toy-train','cookie-bakery','treasure-map','popup-castle','lunar-base','robot-workshop','sky-station','time-portal','submarine'].map(id=>'./assets/backgrounds/scrapbook/'+id+'.webp')];
const absolute=paths.map(p=>new URL(p,self.registration.scope).href),allowed=new Set(absolute);
self.addEventListener('install',event=>event.waitUntil(self.skipWaiting()));
self.addEventListener('activate',event=>event.waitUntil((async()=>{await self.clients.claim();for(const k of await caches.keys())if(k.startsWith('imagine-four-offline-')&&k!==VERSION)await caches.delete(k);})()));
self.addEventListener('message',event=>{if(!['PREPARE','STATUS'].includes(event.data?.type)||!event.ports[0])return;event.waitUntil((async()=>{const port=event.ports[0];try{if(event.data.type==='STATUS'){const exists=(await caches.keys()).includes(VERSION);const cache=exists?await caches.open(VERSION):null;const entries=cache?await Promise.all(absolute.map(url=>cache.match(url))):[];port.postMessage({ok:true,version:VERSION,prepared:exists&&entries.every(Boolean)});return;}const cache=await caches.open(VERSION);for(const url of absolute){const response=await fetch(url,{cache:'reload',credentials:'same-origin'});if(!response.ok||response.redirected)throw Error('파일을 준비하지 못했어요: '+new URL(url).pathname);await cache.put(url,response);}port.postMessage({ok:true});}catch(e){await caches.delete(VERSION);port.postMessage({ok:false,message:e.message});}})());});
self.addEventListener('fetch',event=>{const url=new URL(event.request.url);const key=url.href;if(event.request.method!=='GET'||!allowed.has(key))return;event.respondWith((async()=>{try{const response=await fetch(event.request);if(response.ok&&!response.redirected)return response;throw Error('unavailable');}catch{const cached=await caches.match(key);return cached||Response.error();}})());});
